def translate_ui(text, language='en'):
    """Translate an exact interface string while leaving dynamic/user content intact."""
    value = str(text)
    if language != 'hi':
        return value
    if value in HI:
        return HI[value]
    import re
    patterns = (
        (r'^Bill (.+) was generated successfully\.$', r'बिल \1 सफलतापूर्वक बनाया गया।'),
        (r'^Payment ₹(.+) recorded\.$', r'₹\1 का भुगतान दर्ज किया गया।'),
        (r'^(.+) was added to your products\.$', r'\1 आपके उत्पादों में जोड़ दिया गया।'),
        (r'^(.+) was updated\.$', r'\1 अपडेट किया गया।'),
        (r'^(.+) was deleted\.$', r'\1 हटा दिया गया।'),
        (r'^(.+) was created\.$', r'\1 बनाया गया।'),
        (r'^(.+) was added to (.+)\.$', r'\1 को \2 में जोड़ा गया।'),
        (r'^(.+) is now active\.$', r'\1 अब सक्रिय है।'),
        (r'^(.+) is now inactive\.$', r'\1 अब निष्क्रिय है।'),
        (r'^(\d+) coins redeemed for ₹(.+)\.$', r'₹\2 के \1 कॉइन रिडीम हुए।'),
        (r'^Hello, (.+)$', r'नमस्ते, \1'),
        (r'^Create bill for (.+)$', r'\1 के लिए बिल बनाएँ'),
        (r'^Available at (.+)$', r'यहाँ उपलब्ध: \1'),
        (r'^New styles from (.+) will appear here\.$', r'\1 के नए उत्पाद यहाँ दिखेंगे।'),
        (r'^(.+) offers will appear here\.$', r'\1 के ऑफ़र यहाँ दिखेंगे।'),
        (r'^Coins earned: (.+) · Wallet now (.+) coins$', r'कमाए कॉइन: \1 · वॉलेट में अभी \2 कॉइन'),
        (r'^Total Reward Value ₹([0-9,.]+)$', r'कुल इनाम मूल्य ₹\1'),
        (r'^Worth ₹([0-9,.]+)$', r'मूल्य ₹\1'),
        (r'^Current streak: (\d+) days?$', r'वर्तमान सिलसिला: \1 दिन'),
        (r'^Longest streak: (\d+) days?$', r'सबसे लंबा सिलसिला: \1 दिन'),
        (r'^Add Customer · (.+)$', r'ग्राहक जोड़ें · \1'),
        (r'^Customers · (.+)$', r'ग्राहक · \1'),
        (r'^(.+) customers, including deleted accounts\.$', r'\1 ग्राहक, हटाए गए खातों सहित।'),
        (r'^Bill total ₹([0-9,.]+)$', r'बिल की कुल राशि ₹\1'),
        (r'^Total ₹([0-9,.]+)$', r'कुल ₹\1'),
        (r'^Payment amount \(maximum ₹([0-9,.]+)\)$', r'भुगतान राशि (अधिकतम ₹\1)'),
        (r'^Request (\d+) Coins · ₹([0-9,.]+)$', r'\1 कॉइन का अनुरोध · ₹\2'),
        (r'^Website Coins: (\d+)/100 · Qualifying Bills: (\d+)/3$', r'वेबसाइट कॉइन: \1/100 · योग्य बिल: \2/3'),
        (r'^Website Coins: (\d+)/100 · Qualifying Bills: (\d+)/3\. Reach ₹500 in Website Coin value or complete 3 separate bills above ₹1,000 each\.$', r'वेबसाइट कॉइन: \1/100 · योग्य बिल: \2/3। ₹500 मूल्य के वेबसाइट कॉइन पाएँ या ₹1,000 से अधिक के 3 अलग बिल पूरे करें।'),
        (r'^Current streak: (\d+) days · Longest streak: (\d+) days · Last visit: (.+) · Lifetime Website Coins: (\d+)$', r'वर्तमान सिलसिला: \1 दिन · सबसे लंबा सिलसिला: \2 दिन · पिछली विज़िट: \3 · कुल वेबसाइट कॉइन: \4'),
        (r'^Current streak: (\d+) days · Longest streak: (\d+) days · Total Website Coins earned: (\d+) · Last Website Coin: (.+)$', r'वर्तमान सिलसिला: \1 दिन · सबसे लंबा सिलसिला: \2 दिन · कुल कमाए वेबसाइट कॉइन: \3 · आखिरी वेबसाइट कॉइन: \4'),
        (r'^Current streak: (\d+) days · Longest streak: (\d+) days · Total Website Coins earned: (\d+)$', r'वर्तमान सिलसिला: \1 दिन · सबसे लंबा सिलसिला: \2 दिन · कुल कमाए वेबसाइट कॉइन: \3'),
        (r'^Delete (.+)\?$', r'\1 हटाएँ?'),
        (r'^(.+) will appear here\. Connect with a shop to discover its latest offers\.$', r'नए ऑफ़र यहाँ दिखेंगे। ऑफ़र देखने के लिए किसी दुकान से जुड़ें।'),
        (r'^(.+) offers will appear here\. Shop offers will appear when you connect with a shop\.$', r'दुकान के ऑफ़र यहाँ दिखेंगे। ऑफ़र देखने के लिए किसी दुकान से जुड़ें।'),
        (r'^₹([0-9,.]+) remaining$', r'₹\1 बाकी'),
        (r'^© (\d{4}) Shop Coin$', r'© \1 शॉप कॉइन'),
        (r'^· Application (.+)$', r'· आवेदन \1'),
        (r'^(.+) was created\.$', r'\1 बनाया गया।'),
        (r'^(.+) was added to your products\.$', r'\1 आपके उत्पादों में जोड़ दिया गया।'),
        (r'^(.+) was added to (.+)\.$', r'\1 को \2 में जोड़ा गया।'),
        (r'^(.+) is now active\.$', r'\1 अब सक्रिय है।'),
        (r'^(.+) is now inactive\.$', r'\1 अब निष्क्रिय है।'),
        (r'^(\d+) coins redeemed for ₹(.+)\.$', r'₹\2 के \1 कॉइन रिडीम हुए।'),
    )
    for pattern, replacement in patterns:
        if re.match(pattern, value):
            return re.sub(pattern, replacement, value)
    return value
